package store.model;
import java.util.*;
public final class Order{private final String id;private final Customer customer;private final List<OrderItem> items;private double discount,shipping;private OrderStatus status=OrderStatus.CREATED;public Order(String id,Customer c,Collection<CartItem> source){if(source.isEmpty())throw new IllegalArgumentException("Order needs items");this.id=id;customer=c;items=source.stream().map(i->new OrderItem(i.product(),i.quantity(),i.product().unitPrice())).toList();}public String id(){return id;}public Customer customer(){return customer;}public List<OrderItem> items(){return items;}public OrderStatus status(){return status;}public double subtotal(){return items.stream().mapToDouble(OrderItem::subtotal).sum();}public double discount(){return discount;}public double shipping(){return shipping;}public double total(){return subtotal()-discount+shipping;}public void discount(double v){if(v<0)throw new IllegalArgumentException("Negative discount");discount=Math.min(v,subtotal());}public void shipping(double v){if(v<0)throw new IllegalArgumentException("Negative shipping");shipping=v;}public void status(OrderStatus s){status=s;}}
